css:
.blk{background:#fff;border:2px solid #333;border-radius:10px}
.blk--own{border-color:#e0537f}
.blk--add{border:1.5px dashed #e0537f;color:#e0537f;background:transparent}
/* 枠の有無で種別 */
.card--series{border:1px solid #e3e3e3;border-radius:2px;padding:10px}
.card--plain{border:0;padding:0}
/* キャプションだけ囲う */
.cap{display:inline-block;border:1px solid rgba(255,255,255,.9);border-radius:0;padding:3px 10px;font-size:11px;color:#fff;background:transparent}
/* 差分の区間 */
.gap{position:absolute;left:50%;top:0;bottom:0;border-left:1px dotted #79b7c4}
